{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {node['id']: node for node in nodes}
    children = {node['id']: [] for node in nodes}
    for node in nodes:
        pid = node['parent']
        if pid is not None:
            children[pid].append(node['id'])
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    retained = set(node['id'] for node in nodes)
    removed_order = []
    symbol_counts = {}
    for node in nodes:
        sym = node['symbol']
        if sym in required_symbols:
            symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if not node['removable']:
            continue
        if node['parent'] is None:
            continue
        child_retained = any(cid in retained for cid in children[nid])
        if child_retained:
            continue
        sym = node['symbol']
        if sym in required_symbols and symbol_counts.get(sym, 0) == 1:
            continue
        removed_order.append(nid)
        retained.remove(nid)
        if sym in required_symbols:
            symbol_counts[sym] -= 1
    retained_order = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_order
    }"}
